<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Application\Service\Visibility\UserPersonalApiKeyVisibilityService;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\UserPersonalApiKey;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\Gateway\UserPersonalApiKeyWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserPersonalApiKeyCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserPersonalApiKeyVisibilityService $visibility,
        private readonly UserPersonalApiKeyWriteGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for User personal api key");
        $span = $this->startSpan("Check allow of create usecase for User personal api key");
        try {
            $result = $this->dispatcher->dispatch(new UserPersonalApiKeyCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(UserPersonalApiKeyCreateParams $params): UserPersonalApiKeyCreateResult
    {
        $this->logDebug("Run create usecase for User personal api key");
        $span = $this->startSpan("Run create usecase for User personal api key");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create User personal api key');
            }
            $this->dispatcher->dispatch(new UserPersonalApiKeyCreateCheck($params));
            $enriched = $this->dispatcher->dispatch(new UserPersonalApiKeyCreateEnrich($params, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $entity = UserPersonalApiKey::create($input);
            $result = $this->writer->create(
                $entity,
                fn (UserPersonalApiKey $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserPersonalApiKeyCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
